import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
class AppShell extends StatelessWidget { const AppShell({super.key, required this.child}); final Widget child; static const tabs=['/home','/explore','/community','/ai','/profile']; @override Widget build(BuildContext context){final location=GoRouterState.of(context).uri.toString(); final index=tabs.indexWhere((t)=>location.startsWith(t)); return Scaffold(body:child,bottomNavigationBar:NavigationBar(selectedIndex:index<0?0:index,onDestinationSelected:(i)=>context.go(tabs[i]),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.explore_outlined),label:'Explore'),NavigationDestination(icon:Icon(Icons.forum_outlined),label:'Community'),NavigationDestination(icon:Icon(Icons.auto_awesome_outlined),label:'Zaylo AI'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profile')]),);}}
